UPDATE campaign_delivery SET status = #{toStatus}, last_error = NULL, last_error_code = NULL, reconciliation_required_at = NULL, submitted_at = COALESCE(submitted_at, LEAST(frequency_reserved_at, UTC_TIMESTAMP(6)), created_at) WHERE workspace_id = #{workspaceId} AND id = #{id} AND status IN
#{from}
AND (status != 'failed' OR reconciliation_required_at IS NOT NULL)

mapper.select:
SELECT COUNT(*) FROM campaign_delivery d
JOIN campaign_send s ON s.workspace_id = d.workspace_id AND s.id = d.send_id
WHERE d.workspace_id = #{workspaceId}
  AND d.person_id = #{personId}
  AND s.channel = #{channel}
  AND d.send_id != #{sendId}
  AND d.submitted_at >= #{since}

SELECT COUNT(*) FROM campaign_delivery d
JOIN campaign_send s ON s.workspace_id = d.workspace_id AND s.id = d.send_id
WHERE d.workspace_id = #{workspaceId} AND d.person_id = #{personId}
  AND s.channel = #{channel} AND d.id != #{deliveryId}
  AND (d.submitted_at >= #{since}
    OR (d.submitted_at IS NULL AND d.frequency_reserved_at >= #{since}))

SELECT EXISTS (
  SELECT 1 FROM campaign_delivery
  WHERE workspace_id = #{workspaceId} AND id = #{deliveryId}
    AND status = 'dispatching' AND submitted_at IS NULL


        AND dispatch_lease_owner = #{leaseOwner}
        AND dispatch_lease_until >= UTC_TIMESTAMP(6)

      AND dispatch_lease_owner IS NULL

)

mapper.update:
UPDATE campaign_delivery
SET frequency_reserved_at = #{priorFrequencyReservedAt}
WHERE workspace_id = #{workspaceId} AND id = #{deliveryId}
  AND status = 'dispatching' AND submitted_at IS NULL
  AND #{priorFrequencyReservedAt} IS NOT NULL

    AND dispatch_lease_owner = #{leaseOwner}
    AND dispatch_lease_owner IS NULL

